  function spawnEnemy(boss=false){const angle=Math.random()*Math.PI*2,r=boss?15:10+Math.random()*7;const visual=makeHumanoid(boss);const x=Math.cos(angle)*r,z=Math.sin(angle)*r;visual.root.position.set(x,0,z);const hp=boss?460:80;game.enemies.push({x,z,yaw:0,hp,maxHp:hp,boss,speed:boss?1.55:2.1,attack:0,cooldown:1.2+Math.random()*1.5,windup:0,stagger:0,dead:false,visual,phase:Math.random()*8});if(boss){game.bossSpawned=true;ui.bossHud.hidden=false;toast('O PAVOR SEM ROSTO','A noite tem um rosto. Agora ele vê você.');}}
  function burst(x,y,z,color,n=12){for(let i=0;i<n;i++){const m=mesh(sphereGeo,new THREE.MeshBasicMaterial({color,transparent:true}),scene,x,y,z,.035,.035,.035);game.particles.push({mesh:m,vx:(Math.random()-.5)*3,vy:Math.random()*3,vz:(Math.random()-.5)*3,life:.45+Math.random()*.55});}}
  function attack(kind='light'){const h=game.hero;if(h.attackCd>0||h.dodge>0||h.stamina<(kind==='heavy'?30:18))return;h.attack=kind==='heavy'?.7:.44;h.attackCd=kind==='heavy'?.9:.56;h.attackKind=kind;h.stamina-=kind==='heavy'?30:18;tone(kind==='heavy'?72:118,.16,.07,'sawtooth');}
  function heal(){const h=game.hero;if(h.flasks&&h.health<95){h.flasks--;h.health=Math.min(h.maxHealth,h.health+42);burst(h.x,1,h.z,'#c47750',20);tone(180,.4,.06);updateHud();}}
  function toggleLock(){if(!game)return;const h=game.hero;if(h.locked){h.locked=null;ui.lockLabel.classList.remove('visible');return;}const target=game.enemies.filter(e=>!e.dead).sort((a,b)=>Math.hypot(a.x-h.x,a.z-h.z)-Math.hypot(b.x-h.x,b.z-h.z))[0];if(target){h.locked=target;ui.lockLabel.classList.add('visible');}}
  function damageHero(amount,source){const h=game.hero;if(h.invuln>0||game.over)return;h.health=Math.max(0,h.health-amount);h.hurt=.32;h.invuln=.8;h.stamina=Math.max(0,h.stamina-12);ui.flash.style.opacity='.72';setTimeout(()=>ui.flash.style.opacity='0',130);tone(70,.23,.09,'square');burst(h.x,1.3,h.z,'#963d3a',12);const dx=h.x-source.x,dz=h.z-source.z,len=Math.hypot(dx,dz)||1;h.x+=dx/len*.65;h.z+=dz/len*.65;if(h.health<=0)finish(false);updateHud();}
  function hitCheck(){const h=game.hero;if(h.attack<=0)return;const forward=new THREE.Vector3(Math.sin(h.yaw),0,Math.cos(h.yaw));for(const e of game.enemies){if(e.dead||e.hitLock>0)continue;const dx=e.x-h.x,dz=e.z-h.z,dist=Math.hypot(dx,dz),dot=(dx*forward.x+dz*forward.z)/(dist||1);if(dist<(e.boss?3.9:2.65)&&dot>.2){const dmg=(h.attackKind==='heavy'?76:43)*(e.boss?1:1);e.hp-=dmg;e.stagger=.36;e.hitLock=.34;e.visual.body.rotation.x=-.22;burst(e.x,1.7,e.z,e.boss?'#cf5947':'#d7c09a',16);tone(155,.09,.04,'triangle');if(e.hp<=0){e.dead=true;e.death=.8;game.kills++;h.health=Math.min(h.maxHealth,h.health+3);if(e.boss){scene.remove(e.visual.root);game.enemies=game.enemies.filter(x=>x!==e);finish(true);}else{e.visual.root.scale.setScalar(.001);burst(e.x,.5,e.z,'#be6c4a',25);}updateHud();}}}}
  function finish(win){game.over=true;game.won=win;ui.ending.hidden=false;ui.endingTitle.innerHTML=win?'A NOITE<br><em>RECUA</em>':'A ESTRADA<br><em>TE ENGOLIU</em>';ui.endingText.textContent=win?'O Pavor caiu. Mas, além da colina, outra lua começa a sangrar.':'O silêncio toma a estrada. Até mesmo os mortos esquecem seu nome.';ui.restart.textContent=win?'CAÇAR OUTRA VEZ →':'TENTAR DE NOVO →';ui.bossHud.hidden=true;}
  function update(dt){const h=game.hero;game.time+=dt;h.attack=Math.max(0,h.attack-dt);h.attackCd=Math.max(0,h.attackCd-dt);h.invuln=Math.max(0,h.invuln-dt);h.hurt=Math.max(0,h.hurt-dt);h.stamina=Math.min(100,h.stamina+dt*(h.attack>0?7:22));if(lastToast>0){lastToast-=dt;if(lastToast<=0)ui.toast.classList.remove('show');}
    let ix=(keys.has('d')||keys.has('arrowright')||touch.right?1:0)-(keys.has('a')||keys.has('arrowleft')||touch.left?1:0),iz=(keys.has('s')||keys.has('arrowdown')||touch.back?1:0)-(keys.has('w')||keys.has('arrowup')||touch.forward?1:0);const magnitude=Math.hypot(ix,iz);if(magnitude){ix/=magnitude;iz/=magnitude;}
    if(h.locked&&h.locked.dead){h.locked=null;ui.lockLabel.classList.remove('visible');}if(h.locked){const dx=h.locked.x-h.x,dz=h.locked.z-h.z;h.yaw=Math.atan2(dx,dz);}else if(magnitude)h.yaw=Math.atan2(ix,iz);
    if((keys.has('k')||keys.has(' ')||touch.dodge)&&h.dodge<=0&&h.stamina>=25){h.dodge=.3;h.invuln=.48;h.stamina-=25;const ang=magnitude?Math.atan2(ix,iz):h.yaw;h.x+=Math.sin(ang)*2.5;h.z+=Math.cos(ang)*2.5;burst(h.x,.15,h.z,'#b7a18a',7);tone(95,.1,.04);touch.dodge=false;keys.delete('k');}
