    heroVisual.root.position.set(h.x,0,h.z);heroVisual.root.rotation.y=h.yaw;heroVisual.body.position.y=.05+Math.sin(h.walk)*.035*(magnitude?1:0);heroVisual.legL.rotation.x=Math.sin(h.walk)*.45*(magnitude?1:0);heroVisual.legR.rotation.x=-Math.sin(h.walk)*.45*(magnitude?1:0);heroVisual.armL.rotation.x=-Math.sin(h.walk)*.18*(magnitude?1:0);heroVisual.armR.rotation.x=h.attack>0?-Math.sin((1-h.attack/(h.attackKind==='heavy'?.7:.44))*Math.PI)*1.8:0;heroVisual.sword.rotation.x=h.attack>0?-1.5:0;heroVisual.root.visible=!(h.invuln>0&&Math.floor(game.time*18)%2===0);
    for(const e of game.enemies){e.cooldown-=dt;e.hitLock=Math.max(0,(e.hitLock||0)-dt);e.stagger=Math.max(0,e.stagger-dt);const dx=h.x-e.x,dz=h.z-e.z,dist=Math.hypot(dx,dz)||1;e.yaw=Math.atan2(dx,dz);e.visual.root.rotation.y=e.yaw;e.visual.body.position.y=.05+Math.sin(game.time*3+e.phase)*.025;if(e.stagger<=0){if(dist>(e.boss?3.6:2.15)){e.x+=dx/dist*e.speed*dt;e.z+=dz/dist*e.speed*dt;}else if(e.cooldown<=0&&!e.windup){e.windup=e.boss?.8:.54;}}
      if(e.windup>0){e.windup-=dt;e.visual.armR.rotation.x=-.9;if(e.windup<=0){e.visual.armR.rotation.x=0;e.cooldown=e.boss?2.15:1.7+Math.random()*.6;if(dist<(e.boss?4.1:2.8)&&h.invuln<=0)damageHero(e.boss?24:15,e);else if(e.boss&&dist<8){const p=mesh(sphereGeo,mats.glow,scene,e.x,1.5,e.z,.28,.28,.28);game.projectiles.push({mesh:p,x:e.x,z:e.z,vx:dx/dist*5,vz:dz/dist*5,life:2.5,boss:true});}}}e.x=THREE.MathUtils.clamp(e.x,-25,25);e.z=THREE.MathUtils.clamp(e.z,-25,25);}
    hitCheck();for(const p of game.projectiles){p.life-=dt;p.x+=p.vx*dt;p.z+=p.vz*dt;p.mesh.position.set(p.x,1.5,p.z);if(Math.hypot(p.x-h.x,p.z-h.z)<.9&&h.invuln<=0){p.life=0;damageHero(18,{x:p.x,z:p.z});}}game.projectiles=game.projectiles.filter(p=>{if(p.life<=0){scene.remove(p.mesh);return false;}return true;});
    for(const p of game.particles){p.life-=dt;p.mesh.position.x+=p.vx*dt;p.mesh.position.y+=p.vy*dt;p.mesh.position.z+=p.vz*dt;p.vy-=5*dt;p.mesh.material.opacity=Math.max(0,p.life);if(p.life<=0)scene.remove(p.mesh);}game.particles=game.particles.filter(p=>p.life>0);
    if(!game.bossSpawned){game.spawn-=dt;if(game.kills>=6){spawnEnemy(true);}else if(game.enemies.filter(e=>!e.boss).length<2&&game.spawn<=0){spawnEnemy();game.spawn=2.7+Math.random()*1.8;if(game.kills===0&&game.enemies.length===1)toast('PRIMEIRA MARÉ','O fogo sempre encontra o caminho');}}
    const target=new THREE.Vector3(h.x,1.1,h.z);const camOffset=new THREE.Vector3(-Math.sin(h.yaw)*7,4.2,-Math.cos(h.yaw)*7);if(h.locked){camOffset.x=-Math.sin(h.yaw)*8;camOffset.z=-Math.cos(h.yaw)*8;}const desired=target.clone().add(camOffset);camera.position.lerp(desired,1-Math.exp(-dt*4));camera.lookAt(target.x,target.y+.25,target.z);warm.position.set(-5+Math.sin(game.time)*1.3,1.5,1+Math.cos(game.time)*1.1);
