input.newString:
@media(max-height:500px) and (orientation:landscape){body{padding:4px}.topbar{height:30px}.bottom-bar{height:30px}.game-frame{aspect-ratio:16/9}.mobile-controls{bottom:5px}.intro-copy{transform:scale(.76)}.intro-bottom{bottom:6px}}
/* Classic late-80s/90s dark-fantasy cel-animation finish. */
:root{--bone:#e8d8ba;--muted:#a5967f;--red:#a63832;--gold:#c7a36d}
html,body{background-color:#17110f}
body{background:radial-gradient(ellipse at 50% 45%,#32211d 0,#17110f 68%)}
.game-frame{border-color:#806348;box-shadow:0 22px 65px #000b,0 0 0 5px #1a1310}
.vignette{box-shadow:inset 0 0 65px 16px #100b09a8,inset 0 0 10px #0008}
.intro,.ending{background:linear-gradient(90deg,#120e0dc7 0%,#1a131078 49%,#1a131078 60%,#120e0dc7 100%)}

